// structure.go — the datum of a curve over the projective line and its
// structure pair (A₀, A₁): the curve read over its line, and as the
// lattice pair the lattice-pair chapter asks for; L the fraction field of
// both charts, and the curve read from chart 1; a basis of either chart
// as a basis of the overlap, the line's overlap inside the curve's, and
// the whole overlap generated by any part of chart 0 holding t;
// the cohomology of the structure pair — H⁰ is k, H¹ is finite, and
// χ(O) = 1 − g; the projective line as a curve, of genus zero; and a
// lattice pair of the curve read on its line.

package algebraic_curve

import (
	"github.com/euc-ai/xugo/ext/on"
	. "github.com/euc-ai/xugo/library/authoring"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/algebraic_element"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/field"
	"github.com/euc-ai/xugo/library/proofs/algebra/group/comm_monoid"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/linear_independence"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/module"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/module_dimension"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/module_record"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/submodule"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/comm_ring"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/fractional_ideal"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/integral_element"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_away"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_ideal"
	"github.com/euc-ai/xugo/library/proofs/cartesian/pairs"
	"github.com/euc-ai/xugo/library/proofs/scheme/invertible_lattice_pair"
	"github.com/euc-ai/xugo/library/proofs/scheme/lattice_pair"
	"github.com/euc-ai/xugo/library/proofs/scheme/projective_line"
	"github.com/euc-ai/xugo/library/proofs/scheme/projective_line_duality"
	"github.com/euc-ai/xugo/library/proofs/sets/cardinality"
	"github.com/euc-ai/xugo/library/proofs/sets/finite_set"
	"github.com/euc-ai/xugo/library/proofs/sets/set_algebra"
	"github.com/euc-ai/xugo/library/proofs/sets/set_basic"
	"github.com/euc-ai/xugo/library/proofs/sets/set_order"
	"github.com/euc-ai/xugo/library/registry"
)

// ---------------------------------------------------------------------------
// The datum as a lattice pair, and its two charts
// ---------------------------------------------------------------------------

// CurveOverItsLine — the curve read over the projective line beneath it:
// k is a subfield of L and a field, and t a nonzero member of L
// transcendental over k, as inv(t) is; the charts and their overlap are a
// biaffine datum, its clauses read inside L — three subrings of L, both
// charts inside the overlap, t in chart 0 and inv(t) in chart 1 with
// t · inv(t) = 1, the overlap either chart with its element inverted; the
// charts hold k[t] and k[1/t], meet in k and are each free of finite rank
// over its polynomial ring; the line's own charts k[t] and k[1/t], glued
// along k[t, 1/t], are a biaffine datum inside L, three subrings of L with
// k in both charts and both charts in k[t, 1/t], t in k[t] and inv(t) in
// k[1/t] and in k[t, 1/t] (LineDatum); and L is a module over k, k[t],
// k[1/t] and k[t, 1/t]. A transcendental t is not zero, and its inverse
// is transcendental too (TranscendentalInverse).
var CurveOverItsLine = curveOverItsLineThm{family.Add(registry.ProofEntry{
	Name: "CurveOverItsLine",
	Key:  "prop_379c919358c40ab4",
	Reading: "Gathered so that a member over a curve cites one fact for what each would otherwise " +
		"re-derive from the datum. Of the datum's clauses fraction_field_carrier(field_ring(L), A₀) is " +
		"left out — a member that needs it cites FractionFieldBothCharts, which states it at each " +
		"chart and at the overlap — and A₀₁ ⊆ L.carrier is held only as subring(field_ring(L), A₀₁), " +
		"which implies it (comm_ring.SubringSubset). The line's datum asks of t only that it be nonzero.",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀k A₀ A₁ A₀₁:set(A). ∀t:A.",
		Hypotheses: []string{
			"«wcDatum»",
		},
		Conclusion: "subfield(L, k) ∧ " +
			"field_on(restrict_field(L, k)) ∧ " +
			"t ∈ L.carrier ∧ " +
			"t ≠ L.zero ∧ " +
			"¬algebraic_over(L, k, t) ∧ " +
			"¬algebraic_over(L, k, L.inv(t)) ∧ " +
			"biaffine(«wcOverlap», A₀, A₁, t, L.inv(t)) ∧ " +
			"subring(field_ring(L), A₀₁) ∧ " +
			"subring(field_ring(L), A₀) ∧ " +
			"subring(field_ring(L), A₁) ∧ " +
			"A₀ ⊆ A₀₁ ∧ " +
			"A₁ ⊆ A₀₁ ∧ " +
			"t ∈ A₀ ∧ " +
			"L.inv(t) ∈ A₁ ∧ " +
			"t * L.inv(t) = L.one ∧ " +
			"A₀₁ = ring_away(«wcOverlap», A₀, t) ∧ " +
			"A₀₁ = ring_away(«wcOverlap», A₁, L.inv(t)) ∧ " +
			"«wcPolynomials» ⊆ A₀ ∧ " +
			"«wcInversePolynomials» ⊆ A₁ ∧ " +
			"A₀ ∩ A₁ = k ∧ " +
			"(∃E:set(A). finite(E) ∧ «wcBasisOfChart»(E)) ∧ " +
			"(∃F:set(A). finite(F) ∧ «wcBasisOfInverseChart»(F)) ∧ " +
			"biaffine(«wcRing»(«wcLaurent»), «wcPolynomials», «wcInversePolynomials», t, L.inv(t)) ∧ " +
			"k ⊆ «wcPolynomials» ∧ " +
			"k ⊆ «wcInversePolynomials» ∧ " +
			"«wcPolynomials» ⊆ «wcLaurent» ∧ " +
			"«wcInversePolynomials» ⊆ «wcLaurent» ∧ " +
			"subring(field_ring(L), «wcPolynomials») ∧ " +
			"subring(field_ring(L), «wcInversePolynomials») ∧ " +
			"subring(field_ring(L), «wcLaurent») ∧ " +
			"t ∈ «wcPolynomials» ∧ " +
			"L.inv(t) ∈ «wcInversePolynomials» ∧ " +
			"L.inv(t) ∈ «wcLaurent» ∧ " +
			"module_on(restrict_ring(«wcRing»(«wcLaurent»), k), «wcField») ∧ " +
			"module_on(«wcRing»(«wcPolynomials»), «wcField») ∧ " +
			"module_on(«wcRing»(«wcInversePolynomials»), «wcField») ∧ " +
			"module_on(«wcRing»(«wcLaurent»), «wcField»)",
	},
		func(a *Argument, L field.FieldFact[on.L], k, A0, A1, A01 *Expr[Set[A]], t *Expr[A], curve Fact) {
			datum := a.Unfolded(curve, CurveOverLineDef)
			subfield := a.Have(
				"k is a subfield",
				"subfield(L, k)",
				By(datum))
			tm := a.MemberOf[on.L](t, a.Have(
				"t lies in L",
				"t ∈ L.carrier",
				By(datum)))
			transcendence := a.Have(
				"t is transcendental over k, so it is not zero, and inv(t) is transcendental over k as well",
				"t ≠ L.zero ∧ ¬algebraic_over(L, k, L.inv(t))",
				By(subfield, datum, algebraic_element.TranscendentalInverse.Read(L).At(k, tm)))
			biaffine := a.Have(
				"the charts and their overlap are a biaffine datum",
				"biaffine(«wcOverlap», A₀, A₁, t, L.inv(t))",
				By(datum))
			charts := a.Unfolded(biaffine, lattice_pair.BiaffineDef)
			a.Show(
				"the datum's clauses, the biaffine datum's, its charts and "+
					"overlap subrings of L, and the line's datum at the nonzero t",
				By(
					datum,
					field.SubfieldFieldOn.Read(L).At(k),
					transcendence,
					charts,
					subfield,
					projective_line.LineDatum.Read(L).At(k, tm),
					invertible_lattice_pair.ChartRingsInField.Read(L).At(A0, A1, A01, t)))
		}),
})}

// CurveLatticeData — the structure pair of a curve is an invertible
// lattice pair over the overlap's ring in the field, gluing to the
// overlap, and k is a field with the field's operations inside both
// charts, with the biaffine datum, the overlap inside the field and k a
// subfield: what the lattice-pair chapter asks of a curve. The datum is
// biaffine inside L, so the structure pair is invertible
// (StructurePairInvertible). Its ambient, the A₀₁-span of chart 0, is
// A₀₁: chart 0 lies in the subring A₀₁ and holds one (SpanHoldingOne).
var CurveLatticeData = curveLatticeDataThm{family.Add(registry.ProofEntry{
	Name: "CurveLatticeData",
	Key:  "prop_b80bc7792cf7bafa",
	Reading: "Every conjunct but the ambient is one of CurveOverItsLine's or " +
		"StructurePairInvertible's, gathered so a member over a curve cites one fact; lattice_pair is " +
		"implied by invertible_lattice_pair and stated for the same reason. That the ambient is A₀₁ " +
		"itself, not merely a module both charts span, is what makes H¹(O) the overlap modulo A₀ + A₁.",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀k A₀ A₁ A₀₁:set(A). ∀t:A.",
		Hypotheses: []string{
			"«wcDatum»",
		},
		Conclusion: "A₀₁ ⊆ L.carrier ∧ " +
			"biaffine(«wcOverlap», A₀, A₁, t, L.inv(t)) ∧ " +
			"subfield(L, k) ∧ " +
			"lattice_pair(«wcOverlap», A₀, A₁, «wcField», (A₀, A₁)) ∧ " +
			"«wcStructureAmbient» = A₀₁ ∧ " +
			"invertible_lattice_pair(field_ring(L), A₀, A₁, A₀₁, (A₀, A₁)) ∧ " +
			"field_on(restrict_field(L, k)) ∧ " +
			"k ⊆ A₀ ∩ A₁",
		Abbrev: Abbrev{
			{Name: "wcStructureAmbient", Text: "lattice_pair_ambient(«wcOverlap», «wcField», (A₀, A₁))"},
		},
	},
		func(a *Argument, L field.FieldFact[on.L], k, A0, A1, A01 *Expr[Set[A]], t *Expr[A], curve Fact) {
			datum := a.Simplified(GroupPremises(curve, CurveOverItsLine.Read(L).At(k, A0, A1, A01, t)))
			overlapSubring := a.Have(
				"the overlap is a subring of the field",
				"subring(field_ring(L), A₀₁)",
				By(datum))
			inField := a.Have(
				"so it lies in the field",
				"A₀₁ ⊆ L.carrier",
				By(comm_ring.SubringSubset.Read(overlapSubring)))
			biaffine := a.Have(
				"the charts and their overlap are a biaffine datum",
				"biaffine(«wcOverlap», A₀, A₁, t, L.inv(t))",
				By(datum))

			invertible := a.Have(
				"a biaffine datum inside the field makes the structure pair invertible",
				"invertible_lattice_pair(field_ring(L), A₀, A₁, A₀₁, (A₀, A₁))",
				By(inField, biaffine, invertible_lattice_pair.StructurePairInvertible.Read(L).At(A0, A1, A01, t)))
			lattice := a.Have(
				"so it is a lattice pair over the overlap",
				"lattice_pair(«wcOverlap», A₀, A₁, «wcField», (A₀, A₁))",
				By(a.Unfolded(invertible, invertible_lattice_pair.InvertibleLatticePairDef)))

			chartSubring := a.Have(
				"chart 0 is a subring of the field",
				"subring(field_ring(L), A₀)",
				By(datum))
			chartInOverlap := a.Have(
				"chart 0 lies in the overlap",
				"A₀ ⊆ A₀₁",
				By(datum))
			ambient := a.Have(
				"the ambient is the A₀₁-span of chart 0, a subset of the subring A₀₁ holding one, so it is A₀₁",
				"«wcStructureAmbient» = A₀₁",
				Unfold(lattice_pair.LatticePairAmbientDef),
				By(
					fractional_ideal.SpanHoldingOne.Read(L).At(A01, A0),
					overlapSubring,
					chartInOverlap,
					comm_ring.SubringOne.Read(chartSubring),
					pairs.Fst))

			a.Show(
				"the datum, the invertible structure pair gluing to A₀₁, and the field k inside both charts",
				By(inField, biaffine, datum, lattice, ambient, invertible, set_order.SubsetRefl))
		}),
})}

// FractionFieldBothCharts — the function field is the field of fractions
// of both charts and of the overlap. Of chart 0 the datum says so; a
// fraction p/q of chart 0 already lies over the overlap, which holds
// chart 0; for chart 1, powers inv(t)ᵐ and inv(t)ⁿ carry p and q into A₁
// (A₀₁ is A₁ with inv(t) inverted), and multiplying both by inv(t)ᵐ ·
// inv(t)ⁿ gives a fraction of A₁ whose denominator stays nonzero, no power
// of the unit inv(t) being zero.
var FractionFieldBothCharts = fractionFieldBothChartsThm{family.Add(registry.ProofEntry{
	Name: "FractionFieldBothCharts",
	Key:  "prop_a8548c00a3dcf56c",
	Reading: "The datum states fraction_field_carrier of chart 0 alone; this member states " +
		"it at all three rings, chart 1 and the overlap being what is new, and chart 1's " +
		"clause makes the datum symmetric (CurveSwap). The overlap needs only A₀ ⊆ A₀₁. Chart " +
		"1 needs A₀₁ = A₁[t], in which numerator and denominator each take their own power of " +
		"inv(t) into A₁, and that no power of inv(t) is zero, inv(t) being a unit of L.",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀k A₀ A₁ A₀₁:set(A). ∀t:A.",
		Hypotheses: []string{
			"«wcDatum»",
		},
		Conclusion: "fraction_field_carrier(field_ring(L), A₀) ∧ " +
			"fraction_field_carrier(field_ring(L), A₁) ∧ " +
			"fraction_field_carrier(field_ring(L), A₀₁)",
		Abbrev: Abbrev{
			{Name: "numerator", Text: "monoid_pow(L.mul, L.one, L.inv(t), n) * " +
				"(monoid_pow(L.mul, L.one, L.inv(t), m) * p)"},
			{Name: "denominator", Text: "monoid_pow(L.mul, L.one, L.inv(t), m) * " +
				"(monoid_pow(L.mul, L.one, L.inv(t), n) * q)"},
		},
	},
		func(a *Argument, L field.FieldFact[on.L], k, A0, A1, A01 *Expr[Set[A]], t *Expr[A], curve Fact) {
			fieldRing := a.TermAs[module_record.RingOps[A]]("field_ring(L)")
			chartZero := a.Have(
				"the datum makes L the fraction field of chart 0",
				"fraction_field_carrier(field_ring(L), A₀)",
				By(a.Unfolded(curve, CurveOverLineDef)))
			fractions := a.Have(
				"so every member of L is a fraction of chart 0",
				"∀z:A. z ∈ L.carrier ⇒ ∃a b:A. a ∈ A₀ ∧ b ∈ A₀ ∧ b ≠ L.zero ∧ z * b = a",
				By(chartZero, field.FractionFieldCarrierDef.At(fieldRing, A0)))
			datum := a.Simplified(GroupPremises(curve, CurveOverItsLine.Read(L).At(k, A0, A1, A01, t)))
			overlapSubring := a.Have(
				"the overlap is a subring of the field",
				"subring(field_ring(L), A₀₁)",
				By(datum))
			inField := a.Have(
				"so it lies in the field",
				"A₀₁ ⊆ L.carrier",
				By(comm_ring.SubringSubset.Read(overlapSubring)))
			tInL := a.Have(
				"t lies in the field",
				"t ∈ L.carrier",
				By(datum))
			chartInOverlap := a.Have(
				"chart 0 lies in the overlap",
				"A₀ ⊆ A₀₁",
				By(datum))
			overlap := a.Have(
				"over the overlap the same fraction p/q serves, chart 0 lying in A₀₁",
				"∀z:A. z ∈ L.carrier ⇒ ∃a b:A. a ∈ A₀₁ ∧ b ∈ A₀₁ ∧ b ≠ L.zero ∧ z * b = a",
				Derive(func(b *Argument) {
					z := b.FixAs[A]("z")
					zInL := b.Assume()
					p, q, fraction := b.Unpack2As[A, A](GroupPremises(zInL, fractions.At(z)), "p", "q")
					b.Take(p)
					b.Take(q)
					b.Show(
						"p and q lie in A₀₁ as they lie in A₀",
						BySets(fraction, chartInOverlap))
				}))

			ringL := field.RingOn.Read(L)
			chartRing := a.Have(
				"chart 1, a subring of the field, is a ring under its operations",
				"comm_ring_on(restrict_ring(field_ring(L), A₁))",
				By(datum, comm_ring.SubringRingOn.Read(ringL).At(A1)))
			inverseInChart := a.Have(
				"inv(t) lies in chart 1",
				"L.inv(t) ∈ A₁",
				By(datum))
			away := a.Have(
				"the overlap is chart 1 with inv(t) inverted",
				"A₀₁ = ring_away(«wcOverlap», A₁, L.inv(t))",
				By(datum))
			overlapOps, invT := a.TermAs[module_record.RingOps[A]]("«wcOverlap»"), a.TermAs[A]("L.inv(t)")
			clears := a.Have(
				"so a power of inv(t) carries each member of the overlap into chart 1",
				"∀r:A. r ∈ A₀₁ ⇒ ∃n:num. monoid_pow(L.mul, L.one, L.inv(t), n) * r ∈ A₁",
				a.ForEach(func(r *Expr[A]) Action {
					return By(away, ring_away.RingAwayMember.At(overlapOps, A1, invT, r))
				}))

			powersL := comm_ring.MulMonoidOn.Read(ringL)
			tm := a.MemberOf[on.L](t, tInL)
			invTm := field.InvIn.Read(L).At(tm)
			nonzero := a.Have(
				"no power of inv(t) is zero: tʲ · inv(t)ʲ is one, as t · inv(t) is, and one is not zero",
				"∀j:num. monoid_pow(L.mul, L.one, L.inv(t), j) ≠ L.zero",
				a.ForEach(func(j *Expr[Nat]) Action {
					return By(
						datum,
						field.OneNotZeroOn.Read(L),
						comm_monoid.PowInverseOn.Read(powersL).At(tm, invTm, j),
						comm_ring.MulRightZeroOn.Read(ringL).At(comm_monoid.PowIn.Read(powersL).At(tm, j)))
				}))
			chartOne := a.Have(
				"over chart 1 a fraction p/q of chart 0 serves once "+
					"p and q are both multiplied by inv(t)ᵐ · inv(t)ⁿ",
				"∀z:A. z ∈ L.carrier ⇒ ∃a b:A. a ∈ A₁ ∧ b ∈ A₁ ∧ b ≠ L.zero ∧ z * b = a",
				Derive(func(b *Argument) {
					z := b.FixAs[A]("z")
					zm := b.MemberOf[on.L](z, b.Assume())
					p, q, fraction := b.Unpack2As[A, A](GroupPremises(zm, fractions.At(z)), "p", "q")
					parts := b.Conjuncts(
						fraction,
						"p lies in chart 0",
						"so does q",
						"q is not zero",
						"z · q = p")
					inOverlap := b.Have(
						"p and q lie in the overlap",
						"p ∈ A₀₁ ∧ q ∈ A₀₁",
						BySets(parts[0], parts[1], chartInOverlap))
					m, pCleared := b.ObtainAs[Nat](
						"a power inv(t)ᵐ carries p into chart 1",
						"∃m:num. monoid_pow(L.mul, L.one, L.inv(t), m) * p ∈ A₁",
						By(clears.At(p), inOverlap))
					n, qCleared := b.ObtainAs[Nat](
						"and a power inv(t)ⁿ carries q",
						"∃n:num. monoid_pow(L.mul, L.one, L.inv(t), n) * q ∈ A₁",
						By(clears.At(q), inOverlap))

					pm := b.MemberOf[on.L](p, b.Have(
						"so p lies in the field",
						"p ∈ L.carrier",
						BySets(inOverlap, inField)))
					qm := b.MemberOf[on.L](q, b.Have(
						"and so does q",
						"q ∈ L.carrier",
						BySets(inOverlap, inField)))
					powerM, powerN :=
						comm_monoid.PowIn.Read(powersL).At(invTm, m), comm_monoid.PowIn.Read(powersL).At(invTm, n)
					chartPowers := comm_monoid.PowIn.Read(comm_ring.MulMonoidOn.Read(chartRing))

					numeratorIn := b.Have(
						"inv(t)ⁿ · (inv(t)ᵐ · p) lies in chart 1, a product of members of A₁",
						"«numerator» ∈ A₁",
						By(comm_ring.MulIn.Read(chartRing), chartPowers, inverseInChart, pCleared))
					denominatorIn := b.Have(
						"and so does inv(t)ᵐ · (inv(t)ⁿ · q)",
						"«denominator» ∈ A₁",
						By(comm_ring.MulIn.Read(chartRing), chartPowers, inverseInChart, qCleared))
					denominatorNonzero := b.Have(
						"which is not zero, a product of nonzero members of the field",
						"«denominator» ≠ L.zero",
						By(
							parts[2],
							nonzero.At(m),
							nonzero.At(n),
							field.MulEqZeroOn.Read(L).At(powerM, comm_ring.MulIn.Read(ringL).At(powerN, qm)),
							field.MulEqZeroOn.Read(L).At(powerN, qm)))
					cleared := b.Have(
						"z · q = p multiplied by inv(t)ᵐ · inv(t)ⁿ",
						"z * («denominator») = «numerator»",
						ByArith(
							ringL,
							zm,
							pm,
							qm,
							powerM,
							powerN,
							Scaled(
								b.TermAs[A]("monoid_pow(L.mul, L.one, L.inv(t), m) * monoid_pow(L.mul, L.one, L.inv(t), n)"),
								parts[3])))
					b.Take(b.TermAs[A]("«numerator»"))
					b.Take(b.TermAs[A]("«denominator»"))
					b.Show(
						"so z is the fraction of these two members of chart 1",
						By(numeratorIn, denominatorIn, denominatorNonzero, cleared))
				}))
			chart1Subring := a.Have(
				"chart 1 is a subring of the field",
				"subring(field_ring(L), A₁)",
				By(datum))
			a.Show(
				"L is the fraction field of chart 0, and of chart 1 and the overlap, both inside L",
				By(
					chartZero,
					chartOne,
					overlap,
					inField,
					comm_ring.SubringSubset.Read(chart1Subring),
					field.FractionFieldCarrierDef.At(fieldRing, A1),
					field.FractionFieldCarrierDef.At(fieldRing, A01)))
		}),
})}

// CurveSwap — the curve read from its other chart: inv(t) in place of t
// and the two chart rings exchanged is again a curve over the projective
// line. Inverting twice returns t, so the swapped datum's k[inv(inv(t))]
// is k[t] and its clauses about either chart are the datum's; what is new
// is that inv(t) is transcendental, the biaffine datum read the other way,
// and L the fraction field of chart 1.
var CurveSwap = curveSwapThm{family.Add(registry.ProofEntry{
	Name: "CurveSwap",
	Key:  "prop_a8db7f474b5123fb",
	Reading: "The datum is symmetric in its charts but for its last clause, which " +
		"makes L the fraction field of A₀ alone; read from chart 1 that clause is about " +
		"A₁, and FractionFieldBothCharts supplies it. Every other clause of the swapped " +
		"datum is a clause of the original about the other chart, inv(inv(t)) being t at " +
		"every member of L, zero included, and inv(t) transcendental over k with t, which " +
		"the curve's line records (CurveOverItsLine). Swapping twice returns the datum.",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀k A₀ A₁ A₀₁:set(A). ∀t:A.",
		Hypotheses: []string{
			"«wcDatum»",
		},
		Conclusion: "curve_over_line(L, k, L.inv(t), A₁, A₀, A₀₁)",
	},
		func(a *Argument, L field.FieldFact[on.L], k, A0, A1, A01 *Expr[Set[A]], t *Expr[A], curve Fact) {
			datum := a.Simplified(GroupPremises(curve, CurveOverItsLine.Read(L).At(k, A0, A1, A01, t)))
			tm := a.MemberOf[on.L](t, a.Have(
				"t lies in the field",
				"t ∈ L.carrier",
				By(datum)))
			overlapSubring := a.Have(
				"the overlap is a subring of the field",
				"subring(field_ring(L), A₀₁)",
				By(datum))
			involution := a.Have(
				"inverting twice returns t",
				"L.inv(L.inv(t)) = t",
				By(field.InvInvOn.Read(L).At(tm)))
			swapped := a.Have(
				"the charts exchanged, with inv(t) and t exchanged, are again a biaffine datum",
				"biaffine(«wcOverlap», A₁, A₀, L.inv(t), t)",
				By(
					datum,
					lattice_pair.BiaffineSwap.At(
						a.TermAs[module_record.RingOps[A]]("«wcOverlap»"), A0, A1, t, a.TermAs[A]("L.inv(t)"))))
			fractions := a.Have(
				"L is the fraction field of chart 1",
				"fraction_field_carrier(field_ring(L), A₁)",
				By(curve, FractionFieldBothCharts.Read(L).At(k, A0, A1, A01, t)))
			a.Show(
				"unfolded, with inv(inv(t)) = t, each clause of the "+
					"swapped datum is a clause of the datum or one of these",
				Simp(Fwd(CurveOverLineDef)),
				involution.Rw(),
				By(
					datum,
					comm_ring.SubringSubset.Read(overlapSubring),
					field.InvIn.Read(L).At(tm),
					swapped,
					set_algebra.InterComm.At(A1, A0),
					fractions))
		}),
})}

// BasisSpansOverlap — a basis of chart 0 over k[t] and a basis of
// chart 1 over k[1/t] are both bases of the overlap over k[t, 1/t]: inside
// L the overlap is chart 0 with t inverted and chart 1 with inv(t)
// inverted, k[t, 1/t] is k[t] with t inverted and k[1/t] with inv(t)
// inverted, and a basis survives inverting an element of its scalars
// (BasisAway).
var BasisSpansOverlap = basisSpansOverlapThm{family.Add(registry.ProofEntry{
	Name: "BasisSpansOverlap",
	Key:  "prop_fa09204334659a4f",
	Reading: "Neither basis need be finite: a basis survives inverting an element of its " +
		"scalars whatever its size (BasisAway). What the curve adds is where the inverting happens: " +
		"the datum inverts t inside the overlap's own ring, BasisAway inside L, and the two agree " +
		"because the overlap already holds inv(t); and on chart 1 the scalars become k[1/t] with " +
		"inv(t) inverted, which is the line's k[t, 1/t], spelled through t (LaurentThroughInverse).",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀k A₀ A₁ A₀₁:set(A). ∀t:A.",
		Hypotheses: []string{
			"«wcDatum»",
		},
		Conclusion: "(∀E:set(A). " +
			"    «wcBasisOfChart»(E) ⇒ module_basis(«wcRing»(«wcLaurent»), «wcVectors»(A₀₁), E)) ∧ " +
			"(∀F:set(A). " +
			"    «wcBasisOfInverseChart»(F) ⇒ module_basis(«wcRing»(«wcLaurent»), «wcVectors»(A₀₁), F))",
	},
		func(a *Argument, L field.FieldFact[on.L], k, A0, A1, A01 *Expr[Set[A]], t *Expr[A], curve Fact) {
			datum := a.Simplified(GroupPremises(curve, CurveOverItsLine.Read(L).At(k, A0, A1, A01, t)))
			tm := a.MemberOf[on.L](t, a.Have(
				"t lies in L",
				"t ∈ L.carrier",
				By(datum)))
			invT := a.TermAs[A]("L.inv(t)")
			ringL, fieldOps := field.RingOn.Read(L), a.TermAs[module_record.RingOps[A]]("field_ring(L)")
			nonzero := a.Have(
				"t is not zero",
				"t ≠ L.zero",
				By(datum))
			tInOverlap := a.Have(
				"t lies in the overlap, as chart 0 does",
				"t ∈ A₀₁",
				BySets(datum))
			invInOverlap := a.Have(
				"and so does inv(t), as chart 1 does",
				"L.inv(t) ∈ A₀₁",
				BySets(datum))
			chart0Subring := a.Have(
				"chart 0 is a subring of L",
				"subring(field_ring(L), A₀)",
				By(datum))
			chart1Subring := a.Have(
				"and so is chart 1",
				"subring(field_ring(L), A₁)",
				By(datum))

			overlap0 := a.Have(
				"the overlap is chart 0 with t inverted in L",
				"A₀₁ = ring_away(field_ring(L), A₀, t)",
				CalcEq(
					Leg(
						a.Term("ring_away(«wcOverlap», A₀, t)"),
						"as the datum says",
						By(datum)),
					FinalLeg(
						"the overlap holding inv(t)",
						By(
							ringL,
							datum,
							tInOverlap,
							invInOverlap,
							ring_away.RingAwayInSubring.At(fieldOps, A01, A0, t, invT))),
				))
			overlap1 := a.Have(
				"and chart 1 with inv(t) inverted in L",
				"A₀₁ = ring_away(field_ring(L), A₁, L.inv(t))",
				CalcEq(
					Leg(
						a.Term("ring_away(«wcOverlap», A₁, L.inv(t))"),
						"as the datum says",
						By(datum)),
					FinalLeg(
						"the overlap holding t",
						By(
							ringL,
							datum,
							invInOverlap,
							tInOverlap,
							nonzero,
							field.MulLeftInverseOn.Read(L).At(tm),
							ring_away.RingAwayInSubring.At(fieldOps, A01, A1, invT, t))),
				))
			laurent := a.Have(
				"the Laurent ring read through inv(t) is k[t, 1/t]",
				"ring_away(field_ring(L), «wcInversePolynomials», L.inv(t)) = «wcLaurent»",
				By(datum, projective_line.LaurentThroughInverse.Read(L).At(k, tm)))

			chart0 := a.Have(
				"a basis of chart 0 over k[t] is a basis of the overlap over k[t, 1/t]",
				"∀E:set(A). «wcBasisOfChart»(E) ⇒ module_basis(«wcRing»(«wcLaurent»), «wcVectors»(A₀₁), E)",
				Derive(func(b *Argument) {
					E := b.FixAs[Set[A]]("E")
					basis := b.Assume()
					localized := b.Have(
						"so E is a basis of chart 0 with t inverted, over k[t] with t inverted",
						"module_basis(«wcRing»(«wcLaurent»), «wcVectors»(ring_away(field_ring(L), A₀, t)), E)",
						By(
							datum,
							comm_ring.SubringSubset.Read(chart0Subring),
							basis,
							ring_away.BasisAway.Read(L).At(b.TermAs[Set[A]]("«wcPolynomials»"), A0, t, E)))
					b.Show(
						"which is the overlap",
						overlap0.Rw(),
						By(localized))
				}))
			chart1 := a.Have(
				"a basis of chart 1 over k[1/t] is a basis of the overlap over k[t, 1/t]",
				"∀F:set(A). «wcBasisOfInverseChart»(F) ⇒ module_basis(«wcRing»(«wcLaurent»), «wcVectors»(A₀₁), F)",
				Derive(func(b *Argument) {
					F := b.FixAs[Set[A]]("F")
					basis := b.Assume()
					localized := b.Have(
						"so F is a basis of chart 1 with inv(t) inverted, over k[1/t] with inv(t) inverted",
						"module_basis(«wcRing»(ring_away(field_ring(L), «wcInversePolynomials», L.inv(t))), "+
							"    «wcVectors»(ring_away(field_ring(L), A₁, L.inv(t))), "+
							"    F)",
						By(
							datum,
							comm_ring.SubringSubset.Read(chart1Subring),
							nonzero,
							field.InvEqZeroOn.Read(L).At(tm),
							basis,
							ring_away.BasisAway.Read(L).At(b.TermAs[Set[A]]("«wcInversePolynomials»"), A1, invT, F)))
					b.Show(
						"which is the overlap over k[t, 1/t], k[1/t] with inv(t) inverted being k[t, 1/t]",
						laurent.RwRev(),
						overlap1.Rw(),
						By(localized))
				}))
			a.Show(
				"so a basis of either chart is one of the overlap",
				By(chart0, chart1))
		}),
})}

// LaurentRingInOverlap — the overlap of a curve's two charts contains the
// line's overlap k[t, 1/t]: the overlap is a subring of L holding k[t], t
// and inv(t), so inverting t in k[t] inside the overlap is inverting it
// inside L (RingAwayInSubring), and what is computed inside the overlap
// lies there.
var LaurentRingInOverlap = laurentRingInOverlapThm{family.Add(registry.ProofEntry{
	Name: "LaurentRingInOverlap",
	Key:  "prop_2b83b9a418b6900f",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀k A₀ A₁ A₀₁:set(A). ∀t:A.",
		Hypotheses: []string{
			"«wcDatum»",
		},
		Conclusion: "«wcLaurent» ⊆ A₀₁",
	},
		func(a *Argument, L field.FieldFact[on.L], k, A0, A1, A01 *Expr[Set[A]], t *Expr[A], curve Fact) {
			datum := a.Simplified(GroupPremises(curve, CurveOverItsLine.Read(L).At(k, A0, A1, A01, t)))
			holds := a.Have(
				"the overlap holds k[t] and t, as chart 0 does, and inv(t), as chart 1 does",
				"«wcPolynomials» ⊆ A₀₁ ∧ t ∈ A₀₁ ∧ L.inv(t) ∈ A₀₁",
				BySets(datum))
			fieldOps, polynomials :=
				a.TermAs[module_record.RingOps[A]]("field_ring(L)"), a.TermAs[Set[A]]("«wcPolynomials»")
			away := a.Have(
				"k[t] with t inverted inside the overlap is k[t, 1/t], the overlap holding inv(t)",
				"ring_away(«wcOverlap», «wcPolynomials», t) = «wcLaurent»",
				By(
					field.RingOn.Read(L),
					datum,
					holds,
					ring_away.RingAwayInSubring.At(fieldOps, A01, polynomials, t, a.TermAs[A]("L.inv(t)"))))
			a.Show(
				"which lies in the overlap, the carrier it is computed in",
				away.RwRev(),
				Unfold(ring_away.RingAwayDef),
				BySets())
		}),
})}

// CoordinateSpansOverlap — on a curve over the line, a part of chart 0 holding
// the coordinate t spans the whole overlap: t is a unit there, so the span
// holds the inverse of t times t, which is one.
var CoordinateSpansOverlap = coordinateSpansOverlapThm{family.Add(registry.ProofEntry{
	Name: "CoordinateSpansOverlap",
	Key:  "prop_c4af0f8f5a64d384",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀k A₀ A₁ A₀₁:set(A). ∀t:A. ∀m:set(A).",
		Hypotheses: []string{
			"«wcDatum»",
			"m ⊆ A₀",
			"t ∈ m",
		},
		Conclusion: "ideal_span(«wcOverlap», m) = A₀₁",
	},
		func(
			a *Argument,
			L field.FieldFact[on.L],
			k, A0, A1, A01 *Expr[Set[A]],
			t *Expr[A],
			m *Expr[Set[A]],
			curve, inChart, holdsT Fact,
		) {
			overlap := a.TermAs[RingOps[A]]("«wcOverlap»")
			inverse := a.TermAs[A]("L.inv(t)")
			span := a.TermAs[Set[A]]("ideal_span(«wcOverlap», m)")
			unit := a.Have(
				"the overlap is a subring of L above chart 0, holding t and its inverse, which multiply to one",
				"subring(field_ring(L), A₀₁) ∧ A₀ ⊆ A₀₁ ∧ t ∈ A₀₁ ∧ L.inv(t) ∈ A₀₁ ∧ t * L.inv(t) = L.one",
				BySets(curve, CurveOverItsLine.Read(L).At(k, A0, A1, A01, t)))
			overlapRing := a.Have(
				"the overlap is a ring",
				"comm_ring_on(«wcOverlap»)",
				By(unit, comm_ring.SubringRingOn.Read(field.RingOn.Read(L)).At(A01)))
			spanIdeal := a.Have(
				"the span of m is an ideal of the overlap holding t",
				"ring_ideal(«wcOverlap», ideal_span(«wcOverlap», m)) ∧ t ∈ ideal_span(«wcOverlap», m)",
				By(
					overlapRing,
					inChart,
					holdsT,
					unit,
					set_order.SubsetTrans.At(m, A0, A01),
					ring_ideal.SpanIdeal.Read(overlapRing).At(m),
					ring_ideal.SpanContains.At(overlap, m),
					set_basic.SubsetDef))
			a.Show(
				"so it holds the inverse of t times t, which is one, and an ideal holding one is the whole ring",
				By(
					spanIdeal,
					unit,
					comm_monoid.CommOn.Read(comm_ring.MulMonoidOn.Read(overlapRing)),
					ring_ideal.IdealMul.At(overlap, span, inverse, t),
					ring_ideal.IdealOneIff.Read(overlapRing).At(span)))
		}),
})}

// ---------------------------------------------------------------------------
// The structure pair's cohomology
// ---------------------------------------------------------------------------

// StructureH0 — the global functions of a curve are its constants: H⁰
// of the structure pair is k, of dimension one over k. H⁰ is the space
// A₀ ∩ A₁ over the ring on k, which the datum makes k itself, and a
// subfield is a line over itself, with the basis {one}.
var StructureH0 = structureH0Thm{family.Add(registry.ProofEntry{
	Name: "StructureH0",
	Key:  "prop_c61a6b8455000ac8",
	Reading: "H⁰(O) = k is the datum's clause A₀ ∩ A₁ = k read as cohomology: the curve " +
		"is complete and connected by hypothesis, not by a theorem here. The dimension is " +
		"taken over the overlap's ring read on k, and k, a field, is a line over itself.",
	Build: family.Theorem(Statement{
		Binders: "∀L:field_on(A). ∀k A₀ A₁ A₀₁:set(A). ∀t:A.",
		Hypotheses: []string{
			"«wcDatum»",
		},
		Conclusion: "finite_dimensional(«wcRing»(k), lattice_pair_h0(«wcField», (A₀, A₁))) ∧ " +
			"lattice_pair_h0_dim(«wcOverlap», k, «wcField», (A₀, A₁)) = 1",
	},
		func(a *Argument, L field.FieldFact[on.L], k, A0, A1, A01 *Expr[Set[A]], t *Expr[A], curve Fact) {
			datum := a.Simplified(GroupPremises(curve, CurveOverItsLine.Read(L).At(k, A0, A1, A01, t)))
			fieldK := a.Have(
				"k is a field under the field's operations",
				"field_on(restrict_field(L, k))",
				By(datum))
			fieldOps, kOps :=
				a.TermAs[module_record.RingOps[A]]("field_ring(L)"),
				a.TermAs[module_record.RingOps[A]]("«wcRing»(k)")
			ringK := a.Have(
				"so k is a commutative ring under the field's operations",
				"comm_ring_on(«wcRing»(k))",
				By(
					field.RingOn.Read(fieldK),
					field.FieldRingDef.At(a.TermAs[field.FieldOps[A]]("restrict_field(L, k)")),
					module_record.RestrictRingDef.At(fieldOps, k)))
			// k as a module over itself is L's regular module restricted to k: the same record.
			regularK := module_record.RegularModuleDef.At(kOps)
			restrictedK := module_record.RestrictModuleDef.At(
				a.TermAs[module_record.ModuleOps[A, A]]("«wcField»"), k)

			one, single := a.TermAs[A]("L.one"), a.TermAs[Set[A]]("{L.one}")
			inv := a.TermAs[Fun[A, A]]("L.inv")
			basis := a.Have(
				"{one} is a basis of k over itself",
				"module_basis(«wcRing»(k), «wcVectors»(k), {L.one})",
				By(linear_independence.RegularModuleBasis.Read(ringK), regularK, restrictedK))
			line := a.Have(
				"so k is a line over itself: finite-dimensional, of dimension card({one}) = 1",
				"finite_dimensional(«wcRing»(k), «wcVectors»(k)) ∧ module_dim(«wcRing»(k), «wcVectors»(k)) = 1",
				By(
					datum,
					field.SubfieldRingSubfield.Read(L).At(k, k),
					basis,
					finite_set.FiniteSing.At(one),
					cardinality.CardSing.At(one),
					module_dimension.FiniteBasisDim.Read(module.RegularModuleOn.Read(ringK)).At(inv, single),
					regularK,
					restrictedK))
			a.Show(
				"H⁰ of the structure pair is the space A₀ ∩ A₁ = k over the ring on k",
				Simp(Fwd(lattice_pair.LatticePairH0DimDef), Fwd(lattice_pair.LatticePairH0Def)),
				By(
					line,
					datum,
					pairs.Fst,
					pairs.Snd,
					module_record.RestrictRingDef.At(a.TermAs[module_record.RingOps[A]]("«wcOverlap»"), k),
					module_record.RestrictRingDef.At(fieldOps, k)))
		}),
})}

// StructureH1Finite — H¹ of the structure pair, the overlap modulo
// A₀ + A₁, is finite-dimensional over k: it is the H¹ half of the
// structure pair's finiteness (StructureFinite), the ring on k being the
// overlap's ring read on k.
